def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def rec(rel):
 p=ROOT/rel;im=Image.open(p);return {'file':rel,'sha256':sha(p),'dimensions':list(im.size),'mode':im.mode}
def four(src,dst):
 im=Image.open(ROOT/src);im.resize((im.width*4,im.height*4),Image.Resampling.NEAREST).save(ROOT/dst)
def checker(size):
 im=Image.new('RGB',size,'#293d38');d=ImageDraw.Draw(im)
 for y in range(0,size[1],8):
  for x in range(0,size[0],8):
   if (x//8+y//8)%2:d.rectangle((x,y,x+7,y+7),fill='#3b5146')
 return im
def sheet(items,filename):
 im=Image.new('RGB',(1176,672),'#1c302b');d=ImageDraw.Draw(im);font=ImageFont.load_default(size=14)
